-- Imports all 13 Uncle Ted columns supplied in this conversation.
-- Run supabase/uncle-ted.sql first. This script is idempotent and uses no images.
insert into public.uncle_ted_columns
  (title,slug,teaser,letter,correspondent_name,response,status,published_at,image_url,image_alt,original_url)
values
(
  'Ted Talk: Nairobi winter is killing me but wife has refused with the jiko',
  'nairobi-winter-is-killing-me-but-wife-has-refused-with-the-jiko',
  'A husband shut out in the Nairobi cold asks Uncle Ted how to warm up his marriage.',
  '<p>My wife stopped exciting me, so we rarely get intimate. We can go for as long as six months without doing anything. I have a girlfriend, but unfortunately, she gave birth two weeks ago.</p><p>Recently, I tried getting intimate with my wife because of the cold weather and she told me to go to hell. What should I do?</p>',
  'Joram',
  '<p>Bwana Joram,</p><p>I have a sneaking feeling that your wife suspects or knows you have been lighting another woman’s oven. Knowing women, she is not too excited about you bringing bacteria from “I don’t know where” into her marital bed.</p><p>There is also the likelihood that when you took a sabbatical from your conjugal duties, she got herself a helper who is strumming her guitar way better than you ever did.</p><p>I would, therefore, strongly advise that you join either the Akorino or Roho Israeli sects. Jumping in their keshas all night will warm your chilled bones and take you to heaven as a bonus.</p>',
  'published','2016-06-26T06:00:00Z',null,null,null
),
(
  'Uncle Ted: He’s busy smoking weed, should I dump and forget him?',
  'hes-busy-smoking-weed-should-i-dump-and-forget-him',
  'A schoolgirl wonders whether to leave a boyfriend who has become distant and spends his time smoking weed.',
  '<p>I have been dating since December. Both of us were in Form Four but then he repeated because he changed schools to follow me to my school in a different county. Now, this holiday, he isn’t the same. He doesn’t check up on me like he used to even though he knows I’m sick.</p><p>He is too busy hanging out with his friends and smoking weed. He has changed and is not as caring but claims his feelings for me have not changed. I love him but I know we are about to separate because this is not what I want. Should I just break it off and forget?</p>',
  'Lady Boss',
  '<p>Young lady, didn’t it occur to both of you that him repeating one class to follow you to your school in a different county was nothing short of silly? That cost his parents a year’s school fee.</p><p>If he is incapable of caring about the hardship his own parents endure to raise his fee, you shouldn’t be surprised that he is hanging out with his friends, smoking weed and not caring about a girl he met in December. Have sex with that boy at your own risk.</p>',
  'published','2022-01-01T06:00:00Z',null,null,null
),
(
  'Uncle Ted: My broke husband goes to the barbershop twice a week',
  'my-broke-husband-goes-to-the-barbershop-twice-a-week',
  'Martha is paying every bill while her unemployed husband somehow finds money for two haircuts a week.',
  '<p>We have not been doing well financially since my husband lost his job mid last year. To be honest, there is tension between us because I am now paying all the bills and I don’t think he is trying hard enough to get a job. I can’t even remember the last time we had sex.</p><p>What annoys me is that although we are broke, he has been having his hair shaven twice a week for the last two months. That means he is blowing Sh2,400 on his stupid hair, money that can be used to buy milk for the baby. Why would a man who spends the whole day watching TV care about his hair like a woman?</p>',
  'Martha',
  '<p>My dearest Martha, look on the brighter side of life. Your husband’s job loss has empowered you. Enjoy wearing the pants in the house while it lasts. Now, if you have tension in the house and the memory of lungula is as distant as a bumper maize harvest in Ukambani, your problem shouldn’t be the cash your man is blowing on hair.</p><p>Worry about the girl who lovingly washes his hair at the barbershop, massaging his head and neck to kill his stress while rubbing her boobs on his back and staring at his eyes longingly through the mirror. If she happens to be Rwandese, you are toast, baby. Better start kneading that your broke husband’s neck like unga ya chapati or utapata mwana si wako!</p>',
  'published','2021-09-02T06:00:00Z',null,null,null
),
(
  'Uncle Ted: My secret lover is pregnant and I don’t know what to do!',
  'my-secret-lover-is-pregnant-and-i-dont-know-what-to-do',
  'A student has got two women pregnant and wants Uncle Ted to solve the mess.',
  '<p>I am Evans, a student in one of the campuses. I have been in a relationship for about four years with a certain lady. I impregnated her, meaning she has my baby. I love her so much but her love for me faded.</p><p>I entered another relationship secretly. Unfortunately I impregnated that one too. The other lady does not know and this new one is about to deliver and she loves me so much. What should I do?</p>',
  'Evans',
  '<p>Dear Evans,</p><p>I think you might want to zip up for a bit and spend a little more time studying and reading. Your grammar is bad news and, at this rate, you will graduate without being able to write a job application letter or speak coherently in English.</p><p>Second, you can’t run all over sexing people’s daughters irresponsibly—a condom costs just Sh10—and then turn around and ask me for advice on what to do. Remember how manly and clever you felt when you were jumping secretly from one girl to the next like a jogoo? Now that you are a jobless father of two, use the same manliness and cleverness to feed your tots, treat them and buy them diapers.</p>',
  'published','2021-07-29T06:00:00Z',null,null,null
),
(
  'Uncle Ted: Imagine, my hubby still wears cheap ‘Y’ front underwear',
  'imagine-my-hubby-still-wears-cheap-y-front-underwear',
  'A happily married woman wants to give her dependable but unfashionable husband a makeover.',
  '<p>I have been married for five years and truth be told, my man is a good hubby and daddy. He provides, buys us nice things and is rarely out late. On the rare occasion when he does, he always texts or calls to update me on his whereabouts.</p><p>He is honest, caring and the kind of man who insists on planning for the future with his wife. My only problem with him is that he is just fala. He has the worst taste for clothes but, even then, his body frame is such he always looks like he has slept in his clothes. Worst, I can’t stand his underwear. Who still wears cheap Y-fronts in this time and age? Do you think he will be hurt if I tell him to style up?</p>',
  'Miriam',
  '<p>Young lady,</p><p>I am a little curious about how you got to know what kind underwear other men wear seeing as you are supposed to be a happily married woman, but never mind!</p><p>Anyhow, there is nothing wrong with telling your man to style up. You can even buy him nice clad, throw a few designer magazines around the house and push him into the gym so that he can work that fala body of his into a sculptured sex machine.</p><p>However, when you discover that all your friends have banged him, usitume email ya machozi hapa!</p>',
  'published','2021-09-23T06:00:00Z',null,null,null
),
(
  'Uncle Ted: Should I pay bride price for my cheating wife?',
  'should-i-pay-bride-price-for-my-cheating-wife',
  'Frank’s wife says she has a sponsor, but he is still considering paying her bride price.',
  '<p>I have been married for four years and we have one child. Our marriage was okay for three years, but problems emerged three weeks ago when my wife told me in a heated moment that she has a sponsor.</p><p>I was in the process of paying bride price and she told me that she will not be available on the date set for visiting her parents because she will be visiting her classmate and friend. Should I pay the dowry and divorce her but keep providing my son’s basic needs? I think trying to salvage this marriage will be wasting my time.</p>',
  'Frank',
  '<p>Pay bride price? Are you crazy? Fling her out and use those cows to install a brand new jiko with a humongous behind—and bigger brains—in your house.</p><p>The law doesn’t give a rat’s ass about bride price and not paying will not affect the fact that you are the father of your child. And don’t just meet your son’s basic needs—ensure you have visitation rights set out clearly.</p><p>However, know that after her sponsor has chewed her like Big G and spat her out when the utamu is finished, she will come running back to beg for forgiveness. Or maybe you really don’t want to let go, so you are paying bride price so that she is forever bound to you?</p>',
  'published','2021-08-05T06:00:00Z',null,null,null
),
(
  'Uncle Ted: I meet my husband’s workmate secretly, we only hug tight',
  'i-meet-my-husbands-workmate-secretly-we-only-hug-tight',
  'Jackie secretly meets her husband’s workmate, then catches both men apparently lying about where they are.',
  '<p>I have been seeing my husband’s workmate secretly for a couple of months now. It’s not like we are having sex or anything, but we hug tightly when we meet and I have a feeling he wouldn’t mind sleeping with me. He is a really interesting guy, very funny and I sort of like the way he looks at me. We have been meeting for coffee or dinner, especially when my hubby is out of town.</p><p>Now, last week, we were having dinner and I decided to call my husband to ask how he was doing because he had travelled for work. But guess what? He said that all was okay and that he was in fact shooting drinks with his workmate—who was at the moment sitting right opposite me! I was in shock. Do you think my husband is cheating on me?</p>',
  'Jackie',
  '<p>I don’t think your husband is cheating on you. He was most likely responding to your call from a salon where he had ducked to have his beard waxed and knew that if he told you the truth, you would be upset that the girls might tempt him into accepting a head massage!</p><p>What should worry you is that his workmate is planning to hit you hard with a big rungu, na si ile ya Maasai!</p>',
  'published','2021-11-18T06:00:00Z',null,null,null
),
(
  'Uncle Ted: My chick sent greetings to my best friend in my presence',
  'my-chick-sent-greetings-to-my-best-friend-in-my-presence',
  'A 19-year-old fears his girlfriend’s greeting to his best friend means their relationship is in trouble.',
  '<p>Am Frank from Kisii. Am 19, have got a girl I love most, but we’re not in good terms. Alituma rafiki yangu asalimie tukiwa na yeye, and naona kama hiyo ni kuwa mad. So what should I do?</p>',
  'Frank',
  '<p>Son,</p><p>You will notice that I did not edit the email you sent me. At 19, you are either freshly out of school or perhaps a year into college, so I am not pleased with how you write. You don’t even capitalise your own name, and you write “am” when you mean “I am” or “I’m”. You begin sentences in small letters and the process of writing full words is so tedious you pen “bt” instead of “but”. Surely, son, what would it cost to write a word in full?</p><p>I know you young ones think writing this way is cool. But unfortunately, the outside world is run by a bunch of old, rude, conservative people like me, and they will fling your job application letter into the bin so fast without blinking.</p><p>Now, regarding your girl, relax. Women are smart. They become close with our best friends because they know if we dump them or start misbehaving, only our best pals can wring our ears and tell us to grow up. Also, women love men who don’t get jealous for frivolous reasons. By the way, women will play you anyway—usikonde!</p>',
  'published','2021-09-09T06:00:00Z',null,null,null
),
(
  'Ted Talk: I’m jetting back from USA after 20 years, I can’t find my high school sweetie',
  'im-jetting-back-from-usa-after-20-years-i-cant-find-my-high-school-sweetie',
  'Habib is returning to Kenya after 20 years and is still searching for the high-school sweetheart he left behind.',
  '<p>I am still in love with Fatuma, my first love whom I met 20 years ago at Aga Khan Secondary School Nairobi. After school, I left for the USA but when I came to Kenya, I did not find her.</p><p>I met another woman with whom I have two kids although we are not married. I don’t love her and she knows it. I am very picky with my women.</p><p>I only date light-skinned girls with their own hair, no extensions. I will be moving back to Kenya soon for good to run my own business.</p><p>Am I unable to marry because I am still in love with a woman that probably doesn’t even think about me? If not, I am ready to settle with a Kenya lady.</p>',
  'Habib',
  '<p>Habib, you don’t love this woman, but you have unprotected sex with her for so many years that you have two children? Hahaha!</p><p>So why the hell are you fussing about love? Look, come back home, go to shagz, find a light-skinned, barely literate village girl.</p><p>Clean her up, teach her how to paint her nose and lips, bring her to Nairobi and knock her up. You will fall in love when you are 80.</p><p>Give Nairobi girls a wide berth because they will strangle you like a cat should you moan “Fa-tuh-mah!” at the point of no return.</p>',
  'published','2016-12-04T06:00:00Z',null,null,null
),
(
  'I can’t find my wife’s G-spot, will she leave me?',
  'i-cant-find-my-wifes-g-spot-will-she-leave-me',
  'John has spent weeks searching for something his wife says he has never found and fears she will look elsewhere.',
  '<p>My wife and I have been happily married for the past eight years. But last month, she went for a bridal shower and came back complaining that a woman whose man has never found her G-spot does not know what sex is.</p><p>I have spent the last three weeks looking for that thing, but every time I ask her, “Nimekapata?” she wails, “No-ooo!” I am now worried that she will go out looking for a man who is a better lover. What do I do?</p>',
  'John',
  '<p>Brother John, do you know those Pokot warriors running circles around cops in Baringo? Do you know the fire-spitting politicians and religious prophets you see on TV, or the crack military intelligence officers on dangerous spy missions in Somalia?</p><p>I will tell you this for free: none of these tough chaps have the faintest clue where that darn thing is, or whether it exists in the first place.</p>',
  'published','2017-07-07T06:00:00Z',null,null,null
),
(
  'Uncle Ted: My hubby is killing me with twa-twa every night',
  'my-hubby-is-killing-me-with-twa-twa-every-night',
  'Eunice loves her husband but wants a tactful way to slow down his nightly enthusiasm.',
  '<p>I have been married for the last four years and I want to congratulate my hubby for making me feel like a woman all the time. My problem, however, is that he likes making love to me every night. How can I tell him a woman doesn’t like sex every night without hurting his feelings? I know he can’t look for a mpango wa kando because he loves me and I love him so much too.</p>',
  'Eunice',
  '<p>My dear, you are lucky. There are women in this country who would kill you for raising this “problem”! They have not been touched for months, some even years. They shower, wear sexy perfume, perambulate around the house in their underwear, but the idiot they married is just seated there on the couch, scratching the family jewels and thinking about European football. If you have a nasty, mean, short-tempered workmate or relative, then that is a problem!</p><p>Now, don’t bother telling your man that every night is too much. He is sprinting in a marathon race and I can bet he will run out of gas soon. But better make hay while the “sin” shines because when he hits 45, he will be so kwinished and lucky to get it up once in six months, yet that is the time you will be on fire! Anyway, if the sex is too much, you can get him off your hair by wearing ugly underwear or showering once a week!</p>',
  'published','2021-11-11T06:00:00Z',null,null,null
),
(
  'My wife sneaks to the kitchen to eat at midnight',
  'my-wife-sneaks-to-the-kitchen-to-eat-at-midnight',
  'William discovers that his picky-eater wife’s long midnight bathroom trips actually lead to cold ugali in the kitchen.',
  '<p>We’ve been married for six months. My wife is a picky eater who barely nibbles at her food. But about three weeks after we moved in together, I noticed that she would wake up at around midnight to go to the toilet.</p><p>What disturbed me is that her toilet trips were taking rather too long. Curious, I tiptoed to check up on her last week.</p><p>To my shock, she was sitting on the kitchen floor eating cold ugali like a nonsense. Should I report her to her mother?</p>',
  'William',
  '<p>The supplied screenshot ends after William’s letter; Uncle Ted’s response was not visible. Add the original response in the admin editor when it becomes available.</p>',
  'published','2019-12-25T06:00:00Z',null,null,null
),
(
  'I got pregnant with another guy two days before my wedding',
  'i-got-pregnant-with-another-guy-two-days-before-my-wedding',
  'Eve fears her son may have been conceived during a final encounter with another man shortly before her wedding.',
  '<p>Before I got married, I was dating two men. Two days before our wedding, I had sex with the other guy to say goodbye to single life. He cheated me that he was using a condom but in the middle of action, he pulled it off without my knowledge. I swallowed a pill but I think it backfired because my son looks exactly like him.</p><p>The saving grace is my hubby has never suspected because the two men have the same skin tone, plus he loves that boy like crazy. But recently, I have been feeling guilty about keeping this secret from him. Should I confess?</p>',
  'Eve',
  '<p>Dear Eve,</p><p>Next year promises to be thoroughly miserable. The rains might be dodgy. The sun will be hot. Crops might fail. And politicians will be yelling nonsense in our ears from dawn to dusk. The economy being what it is, and given the colossal amounts of money people have stolen, chances are there won’t be anything to eat around here.</p><p>The supplied screenshot cuts off the remainder of Uncle Ted’s response. Complete it in the admin editor if the original becomes available.</p>',
  'published','2020-09-09T06:00:00Z',null,null,null
)
